-- 第四阶段：在 0005 之后执行一次。所有金额列均为整数分。
ALTER TABLE lessons ADD COLUMN format TEXT NOT NULL DEFAULT 'individual';
UPDATE lessons SET format=COALESCE((SELECT c.format FROM course_types c WHERE c.tenant_id=lessons.tenant_id AND c.id=lessons.course_type_id),'individual');
ALTER TABLE lessons ADD COLUMN override_rate INTEGER CHECK(override_rate IS NULL OR (typeof(override_rate)='integer' AND override_rate>=0));
ALTER TABLE lessons ADD COLUMN override_basis TEXT NOT NULL DEFAULT 'legacy';
ALTER TABLE lessons ADD COLUMN locked_rate INTEGER CHECK(locked_rate IS NULL OR typeof(locked_rate)='integer');
ALTER TABLE settlements ADD COLUMN status TEXT NOT NULL DEFAULT 'draft';
ALTER TABLE settlements ADD COLUMN submitted_by TEXT;
ALTER TABLE settlements ADD COLUMN submitted_at INTEGER;
ALTER TABLE settlements ADD COLUMN submitted_revision INTEGER;
ALTER TABLE settlements ADD COLUMN approved_by TEXT;
ALTER TABLE settlements ADD COLUMN approved_at INTEGER;
ALTER TABLE settlements ADD COLUMN snapshot_token TEXT;
ALTER TABLE settlements ADD COLUMN reason TEXT NOT NULL DEFAULT '';
ALTER TABLE settlements ADD COLUMN total_amount INTEGER NOT NULL DEFAULT 0 CHECK(typeof(total_amount)='integer');
ALTER TABLE settlements ADD COLUMN tuition_amount INTEGER NOT NULL DEFAULT 0 CHECK(typeof(tuition_amount)='integer');
ALTER TABLE settlements ADD COLUMN cost_amount INTEGER NOT NULL DEFAULT 0 CHECK(typeof(cost_amount)='integer');
ALTER TABLE settlements ADD COLUMN profit_amount INTEGER NOT NULL DEFAULT 0 CHECK(typeof(profit_amount)='integer');
CREATE TABLE teacher_rates(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,teacher_id TEXT NOT NULL,course_type_id TEXT NOT NULL,format TEXT NOT NULL,rate_basis TEXT NOT NULL DEFAULT 'legacy',rate INTEGER NOT NULL CHECK(typeof(rate)='integer' AND rate>=0),effective_from TEXT NOT NULL,effective_to TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,teacher_id) REFERENCES teachers(tenant_id,id),FOREIGN KEY(tenant_id,course_type_id) REFERENCES course_types(tenant_id,id));
CREATE TABLE teacher_payments(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,teacher_id TEXT NOT NULL,month TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0),paid_at TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,teacher_id) REFERENCES teachers(tenant_id,id));
CREATE TABLE teacher_adjustments(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,teacher_id TEXT NOT NULL,month TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer'),reason TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,teacher_id) REFERENCES teachers(tenant_id,id));
CREATE TABLE other_costs(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,date TEXT NOT NULL,category TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>=0),note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
CREATE TABLE payroll_snapshots(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,month TEXT NOT NULL,snapshot_token TEXT NOT NULL,lesson_id TEXT NOT NULL,teacher_id TEXT NOT NULL,rate INTEGER NOT NULL CHECK(typeof(rate)='integer'),rate_basis TEXT NOT NULL,quantity REAL NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer'),lesson_json TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,lesson_id) REFERENCES lessons(tenant_id,id),FOREIGN KEY(tenant_id,teacher_id) REFERENCES teachers(tenant_id,id));
CREATE INDEX teacher_rates_scope ON teacher_rates(tenant_id,teacher_id,course_type_id,effective_from,effective_to);
CREATE INDEX teacher_payments_scope ON teacher_payments(tenant_id,month,teacher_id);
CREATE INDEX teacher_adjustments_scope ON teacher_adjustments(tenant_id,month,teacher_id);
CREATE INDEX other_costs_scope ON other_costs(tenant_id,date);
CREATE INDEX payroll_snapshots_scope ON payroll_snapshots(tenant_id,month,snapshot_token,teacher_id);
CREATE TRIGGER precision_packages_insert BEFORE INSERT ON packages WHEN ABS(NEW.units_total*100-ROUND(NEW.units_total*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_packages_update BEFORE UPDATE OF units_total ON packages WHEN NEW.units_total IS NOT OLD.units_total AND ABS(NEW.units_total*100-ROUND(NEW.units_total*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_package_transactions_insert BEFORE INSERT ON package_transactions WHEN ABS(NEW.delta*100-ROUND(NEW.delta*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_package_transactions_update BEFORE UPDATE OF delta ON package_transactions WHEN NEW.delta IS NOT OLD.delta AND ABS(NEW.delta*100-ROUND(NEW.delta*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_course_types_insert BEFORE INSERT ON course_types WHEN ABS(NEW.units_per_lesson*100-ROUND(NEW.units_per_lesson*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_course_types_update BEFORE UPDATE OF units_per_lesson ON course_types WHEN NEW.units_per_lesson IS NOT OLD.units_per_lesson AND ABS(NEW.units_per_lesson*100-ROUND(NEW.units_per_lesson*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_schedule_templates_insert BEFORE INSERT ON schedule_templates WHEN ABS(NEW.units*100-ROUND(NEW.units*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_schedule_templates_update BEFORE UPDATE OF units ON schedule_templates WHEN NEW.units IS NOT OLD.units AND ABS(NEW.units*100-ROUND(NEW.units*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_lessons_insert BEFORE INSERT ON lessons WHEN ABS(NEW.units*100-ROUND(NEW.units*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_lessons_update BEFORE UPDATE OF units ON lessons WHEN NEW.units IS NOT OLD.units AND ABS(NEW.units*100-ROUND(NEW.units*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_lesson_participants_insert BEFORE INSERT ON lesson_participants WHEN ABS(NEW.deducted*100-ROUND(NEW.deducted*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER precision_lesson_participants_update BEFORE UPDATE OF deducted ON lesson_participants WHEN NEW.deducted IS NOT OLD.deducted AND ABS(NEW.deducted*100-ROUND(NEW.deducted*100))>0.0000001 BEGIN SELECT RAISE(ABORT,'quantity_precision'); END;
CREATE TRIGGER snapshot_no_update BEFORE UPDATE ON payroll_snapshots BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER snapshot_no_delete BEFORE DELETE ON payroll_snapshots BEGIN SELECT RAISE(ABORT,'append only'); END;

-- 新排课程限定时长与最低课时；已有历史记录在未改动这些字段时保留原值。
CREATE TRIGGER course_limits_course_types_insert BEFORE INSERT ON course_types WHEN (NEW.units_per_lesson<1 OR NEW.default_minutes NOT IN (30,45,60)) BEGIN SELECT RAISE(ABORT,'course_duration_or_units'); END;
CREATE TRIGGER course_limits_course_types_update BEFORE UPDATE ON course_types WHEN ((NEW.units_per_lesson IS NOT OLD.units_per_lesson AND NEW.units_per_lesson<1) OR (NEW.default_minutes IS NOT OLD.default_minutes AND NEW.default_minutes NOT IN (30,45,60))) BEGIN SELECT RAISE(ABORT,'course_duration_or_units'); END;
CREATE TRIGGER course_limits_schedule_templates_insert BEFORE INSERT ON schedule_templates WHEN (NEW.units<1 OR NEW.duration NOT IN (30,45,60)) BEGIN SELECT RAISE(ABORT,'course_duration_or_units'); END;
CREATE TRIGGER course_limits_schedule_templates_update BEFORE UPDATE ON schedule_templates WHEN ((NEW.units IS NOT OLD.units AND NEW.units<1) OR (NEW.duration IS NOT OLD.duration AND NEW.duration NOT IN (30,45,60))) BEGIN SELECT RAISE(ABORT,'course_duration_or_units'); END;
CREATE TRIGGER course_limits_lessons_insert BEFORE INSERT ON lessons WHEN (NEW.units<1 OR NEW.duration NOT IN (30,45,60)) BEGIN SELECT RAISE(ABORT,'course_duration_or_units'); END;
CREATE TRIGGER course_limits_lessons_update BEFORE UPDATE ON lessons WHEN ((NEW.units IS NOT OLD.units AND NEW.units<1) OR (NEW.duration IS NOT OLD.duration AND NEW.duration NOT IN (30,45,60))) BEGIN SELECT RAISE(ABORT,'course_duration_or_units'); END;
